#!/usr/bin/env node
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { createHash } from "node:crypto";
import { spawnSync } from "node:child_process";

const LABEL = "pfotentechnik-seo-copilot-essential-reports-1.0.0";
const ENTRIES = [{"file":"apps/pfotentechnik/src/lib/seo/advisor/loadWorkPackages.ts","action":"replace","beforeHash":"874481ff986b1995d30415d94b4d6d08df1cba15ae864000e70cc3396294e633","beforeBase64":"","afterHash":"e19821afcf65305779e4b19347097a28209f2c0d39c25dbc50e455d5400e4a9d","afterBase64":""},{"file":"apps/pfotentechnik/src/pages/admin/seo/advisor.astro","action":"replace","beforeHash":"a09003981da8c417f3b63b563fff0d8ee3ed1a9d853407d599a4f5ff3be2728e","beforeBase64":"","afterHash":"2c6c17568aae21216823942d66a5d5d3027c9da24aad7fdd17bc2629038b2121","afterBase64":""},{"file":"apps/pfotentechnik/test/seo-copilot-compact-report.test.mjs","action":"create","beforeHash":null,"beforeBase64":null,"afterHash":"e1c42d9b323034f305f200c68ad02f3008c677cce630b5e05c6205392e61c82f","afterBase64":""}];
const normalize = (value) => value.replace(/\r\n/g, "\n");
const hash = (value) => createHash("sha256").update(normalize(value), "utf8").digest("hex");
const decode = (value) => Buffer.from(value, "base64").toString("utf8");
const timestamp = () => new Date().toISOString().replace(/[:.]/g, "-");
const fail = (message) => { console.error(message); process.exitCode = 1; };

const root = process.cwd();
const marker = path.join(root, "apps", "pfotentechnik", "package.json");
if (!fs.existsSync(marker)) {
  fail("Abbruch: Bitte den Installer im Root von affiliate-template ausführen.");
} else {
  const states = [];
  const conflicts = [];

  for (const entry of ENTRIES) {
    const target = path.join(root, entry.file);
    const exists = fs.existsSync(target);
    if (!exists) {
      if (entry.action === "create") states.push({ entry, target, state: "before", source: null });
      else conflicts.push(`${entry.file} fehlt.`);
      continue;
    }
    const source = fs.readFileSync(target, "utf8");
    const currentHash = hash(source);
    if (currentHash === entry.afterHash) states.push({ entry, target, state: "after", source });
    else if (entry.beforeHash && currentHash === entry.beforeHash) states.push({ entry, target, state: "before", source });
    else if (entry.action === "create") conflicts.push(`${entry.file} existiert bereits mit unbekanntem Inhalt.`);
    else conflicts.push(`${entry.file} weicht vom erwarteten Ausgangs- und Zielstand ab.`);
  }

  if (conflicts.length) {
    console.error("Abbruch: Der kompakte SEO-Copilot kann nicht konfliktfrei installiert werden:");
    for (const conflict of conflicts) console.error(` - ${conflict}`);
    console.error("Es wurde nichts verändert. Bestehende Änderungen bleiben erhalten.");
    process.exitCode = 1;
  } else {
    const changed = states.filter((item) => item.state === "before");
    if (!changed.length) {
      console.log("Bereits installiert. Keine Änderungen erforderlich.");
    } else {
      const backupRoot = path.join(root, ".patch-backups", `${LABEL}-${timestamp()}`);
      fs.mkdirSync(backupRoot, { recursive: true });
      const applied = [];
      try {
        for (const item of changed) {
          if (item.source !== null) {
            const backup = path.join(backupRoot, item.entry.file);
            fs.mkdirSync(path.dirname(backup), { recursive: true });
            fs.copyFileSync(item.target, backup);
          }
          fs.mkdirSync(path.dirname(item.target), { recursive: true });
          const eol = item.source?.includes("\r\n") ? "\r\n" : os.EOL === "\r\n" ? "\r\n" : "\n";
          fs.writeFileSync(item.target, normalize(decode(item.entry.afterBase64)).replace(/\n/g, eol), "utf8");
          applied.push(item);
        }

        const test = spawnSync(process.execPath, [
          "--test",
          "apps/pfotentechnik/test/seo-copilot-compact-report.test.mjs",
        ], { cwd: root, stdio: "inherit", shell: false });
        if (test.status !== 0) throw new Error("Der fokussierte SEO-Copilot-Test ist fehlgeschlagen.");

        console.log(`Installiert: ${changed.length} Dateien geändert.`);
        console.log(`Backup: ${backupRoot}`);
        console.log("SEO Co-Pilot: maximal 12 wichtige Pakete; keine vollständigen Live-Analysen mehr.");
        console.log("Release-Gate und vollständige Fachreports bleiben unverändert.");
      } catch (error) {
        for (const item of applied.reverse()) {
          const backup = path.join(backupRoot, item.entry.file);
          if (fs.existsSync(backup)) fs.copyFileSync(backup, item.target);
          else if (item.entry.action === "create" && fs.existsSync(item.target)) fs.unlinkSync(item.target);
        }
        console.error("Validierung fehlgeschlagen. Die Änderungen wurden automatisch zurückgerollt.");
        console.error(`Backup: ${backupRoot}`);
        fail(error instanceof Error ? error.message : String(error));
      }
    }
  }
}
